@layer moduix.components {
  .content {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    box-shadow: var(--moduix-shadow-lg);
    outline: 0;

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      pointer-events: none;
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }

    /* Dims panels that are not on top of the stack. */
    &[data-behind] {
      opacity: 0.55;
    }
  }

  .header {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-3);
    min-height: var(--moduix-size-xl);
    padding: var(--moduix-spacing-2) var(--moduix-spacing-3);
    border-bottom: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    background-color: var(--moduix-color-muted);
    cursor: grab;
    user-select: none;

    &[data-dragging] {
      cursor: grabbing;
    }

    /* A minimized panel is only the header, so the content border already closes it. */
    &[data-minimized] {
      border-bottom-color: transparent;
    }
  }

  .title {
    display: inline-flex;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    margin: 0;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--moduix-spacing-1);
  }

  .controlButton {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-size-sm);
    height: var(--moduix-size-sm);
    margin: 0;
    padding: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-sm);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }

    /* :not() keeps this above the CloseButton hover that FloatingPanelCloseIcon also carries. */
    @media (hover: hover) {
      &:hover:not([data-disabled]) {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active {
      background-color: var(--moduix-color-accent);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-focus-ring-inset-width) * -1);
    }

    &:is([data-disabled], :disabled) {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
    }
  }

  .dragIndicator {
    display: inline-flex;
    flex: none;
    color: var(--moduix-color-muted-foreground);

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }
  }

  .body {
    box-sizing: border-box;
    flex: 1 1 auto;
    min-height: 0;
    overflow: auto;
    padding: var(--moduix-spacing-4);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .footer {
    box-sizing: border-box;
    display: flex;
    flex: none;
    align-items: center;
    justify-content: flex-end;
    gap: var(--moduix-spacing-2);
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);

    &[data-minimized] {
      display: none;
    }
  }

  /* Ark positions each handle inline; the wrapper only sets its hit area. */
  .resizeTrigger {
    &:is([data-axis='n'], [data-axis='s']) {
      height: var(--moduix-spacing-2);
    }

    &:is([data-axis='e'], [data-axis='w']) {
      width: var(--moduix-spacing-2);
    }

    &:is([data-axis='ne'], [data-axis='nw'], [data-axis='se'], [data-axis='sw']) {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }
}

import type {
  FloatingPanelResizeTriggerAxis,
  FloatingPanelStage,
} from '@ark-ui/vue/floating-panel';
import { MaximizeIcon, MinusIcon, RestoreIcon } from '@/lib/moduix/icons/ui/Icons';

export const resizeTriggerAxes = [
  'n',
  'e',
  's',
  'w',
  'ne',
  'se',
  'sw',
  'nw',
] satisfies FloatingPanelResizeTriggerAxis[];

export const stageIcons = {
  default: RestoreIcon,
  maximized: MaximizeIcon,
  minimized: MinusIcon,
} satisfies Record<FloatingPanelStage, unknown>;

import {
  FloatingPanelContext,
  useFloatingPanel,
  useFloatingPanelContext,
} from '@ark-ui/vue/floating-panel';
import { resizeTriggerAxes } from './floating-panel.types';
import FloatingPanel from './FloatingPanel.vue';
import FloatingPanelBody from './FloatingPanelBody.vue';
import FloatingPanelCloseIcon from './FloatingPanelCloseIcon.vue';
import FloatingPanelCloseTrigger from './FloatingPanelCloseTrigger.vue';
import FloatingPanelContent from './FloatingPanelContent.vue';
import FloatingPanelControl from './FloatingPanelControl.vue';
import FloatingPanelDragIndicator from './FloatingPanelDragIndicator.vue';
import FloatingPanelDragTrigger from './FloatingPanelDragTrigger.vue';
import FloatingPanelFooter from './FloatingPanelFooter.vue';
import FloatingPanelHeader from './FloatingPanelHeader.vue';
import FloatingPanelPositioner from './FloatingPanelPositioner.vue';
import FloatingPanelResizeTrigger from './FloatingPanelResizeTrigger.vue';
import FloatingPanelResizeTriggerGroup from './FloatingPanelResizeTriggerGroup.vue';
import FloatingPanelRootProvider from './FloatingPanelRootProvider.vue';
import FloatingPanelStageTrigger from './FloatingPanelStageTrigger.vue';
import FloatingPanelTitle from './FloatingPanelTitle.vue';
import FloatingPanelTrigger from './FloatingPanelTrigger.vue';

export {
  FloatingPanel,
  FloatingPanelBody,
  FloatingPanelCloseIcon,
  FloatingPanelCloseTrigger,
  FloatingPanelContent,
  FloatingPanelContext,
  FloatingPanelControl,
  FloatingPanelDragIndicator,
  FloatingPanelDragTrigger,
  FloatingPanelFooter,
  FloatingPanelHeader,
  FloatingPanelPositioner,
  FloatingPanelResizeTrigger,
  FloatingPanelResizeTriggerGroup,
  FloatingPanelRootProvider,
  FloatingPanelStageTrigger,
  FloatingPanelTitle,
  FloatingPanelTrigger,
  resizeTriggerAxes,
  useFloatingPanel,
  useFloatingPanelContext,
};

export type {
  FloatingPanelAnchorPositionDetails,
  FloatingPanelBodyProps,
  FloatingPanelCloseTriggerProps,
  FloatingPanelContentProps,
  FloatingPanelContextProps,
  FloatingPanelControlProps,
  FloatingPanelDragTriggerProps,
  FloatingPanelHeaderProps,
  FloatingPanelIntlTranslations,
  FloatingPanelOpenChangeDetails,
  FloatingPanelPoint,
  FloatingPanelPositionChangeDetails,
  FloatingPanelPositionerProps,
  FloatingPanelResizeTriggerAxis,
  FloatingPanelResizeTriggerProps,
  FloatingPanelRootEmits,
  FloatingPanelRootProviderEmits,
  FloatingPanelSize,
  FloatingPanelSizeChangeDetails,
  FloatingPanelStage,
  FloatingPanelStageChangeDetails,
  FloatingPanelStageTriggerProps,
  FloatingPanelTitleProps,
  FloatingPanelTriggerProps,
  UseFloatingPanelContext,
  UseFloatingPanelProps,
  UseFloatingPanelReturn,
} from '@ark-ui/vue/floating-panel';

export type { Props as FloatingPanelRootProps } from './FloatingPanel.vue';
export type { Props as FloatingPanelRootProviderProps } from './FloatingPanelRootProvider.vue';
